import { inflate } from './dist/inflate.js';

// The entry for `pkg-a` does not cover `pkg-b`, though it lies in the `node_modules` of `pkg-a`.
export const fromStream = stream => Array.fromAsync(stream);

// The entry for `pkg-b` covers its `dist` only.
export const decompress = stream => stream.pipeThrough(new DecompressionStream('gzip'));

export { inflate };
